def tool(text):
    import re
    # Look for a citation that includes the date 03/12/23 and mentions Ukrainian MoD
    pattern = re.compile(r"Ukrainian\s+MoD.*?03/12/23", re.IGNORECASE)
    match = pattern.search(text)
    if match:
        # Return the surrounding sentence for context
        start = max(text.rfind('\n', 0, match.start()), 0)
        end = text.find('\n', match.end())
        if end == -1:
            end = len(text)
        return text[start:end].strip()
    return "Citation not found"

