    ["No relevant citation here.", "Citation not found"]
]

def tool(text):
    # Regex to match candidate names with common variations (e.g., 'Lula da Silva' or 'Lula daSilva')
    pattern = r'\b(Lula(?:\s+da\s+Silva|daSilva)|Jair(?:\s+Bolsonaro|Bolsonaro))\b'
    return ''.join(re.findall(pattern, text, re.IGNORECASE))

